const siteByInstitution = new Map(FEDERAL_SITES.map((site) => [site.institution, site]));
/** An institution's row, sourced or not; undefined only for an id the table does not list. */
export function federalSite(institution) {
    return siteByInstitution.get(institution);
}
/** An institution's headquarters point, or undefined where its row records no location. */
export function federalSitePoint(institution) {
    const site = siteByInstitution.get(institution);
    if (!site || site.location !== "sourced" || site.lat === undefined || site.lon === undefined)
        return undefined;
    return { lat: site.lat, lon: site.lon };
}
